-- 为视频补充独立提示词，保留已有草稿、已发布规则和自定义模板。
UPDATE productConfiguration SET draft = JSON_SET(draft, '$.prompts.video', COALESCE(JSON_EXTRACT(draft, '$.prompts.video'), CAST('{"reference":"以首帧图片中的人物身份为基础生成自然连贯的短视频，保持人物一致。将本次场景与动作要求表现为连续运动，而非静止照片。服装、场景、表情、镜头运动和声音均以本次要求为准。\\n\\n本次视频要求：\\n{{scene}}","text":"按本次场景与动作要求生成自然连贯的短视频，而非静止照片。角色外貌参考只补充本次未指定的人物细节，冲突时以本次要求为准。\\n角色外貌参考：{{appearance}}\\n\\n本次视频要求：\\n{{scene}}"}' AS JSON))), published = JSON_SET(published, '$.prompts.video', COALESCE(JSON_EXTRACT(published, '$.prompts.video'), CAST('{"reference":"以首帧图片中的人物身份为基础生成自然连贯的短视频，保持人物一致。将本次场景与动作要求表现为连续运动，而非静止照片。服装、场景、表情、镜头运动和声音均以本次要求为准。\\n\\n本次视频要求：\\n{{scene}}","text":"按本次场景与动作要求生成自然连贯的短视频，而非静止照片。角色外貌参考只补充本次未指定的人物细节，冲突时以本次要求为准。\\n角色外貌参考：{{appearance}}\\n\\n本次视频要求：\\n{{scene}}"}' AS JSON))), revision = revision + 1, publishedRevision = publishedRevision + 1, publishedAt = CURRENT_TIMESTAMP WHERE JSON_EXTRACT(draft, '$.prompts.video') IS NULL OR JSON_EXTRACT(published, '$.prompts.video') IS NULL;
